236	    /**
237	     * Create and persist a brand-new owner from the supplied fields, returning the
238	     * {@code 201 Created} response for it. This gathers the whole create pipeline in one
239	     * place — map the fields, {@link #normalizeNewOwner normalise} them, apply the daily
240	     * and city gates (each with its own rejection status), resolve any household,
241	     * {@link #assignDerivedAttributes derive the create-time attributes} (including the
242	     * household level ceiling that caps the owner's membership level), save, audit and
243	     * build the response with its {@code Location} header — so {@link #addOwner} itself
244	     * stays a thin entry point. An owner joining an existing household is admitted (its
245	     * membership level is capped to one above the household maximum rather than rejected):
246	     * two owners sharing a last name and postcode but with different telephones are no
247	     * longer a hard duplicate but a soft match. Duplicate detection is the single
248	     * {@link Owner#getIdentityKey() identity key}: a create whose identity key matches an
249	     * existing, non-deleted owner is rejected with {@code 409 Conflict}.
250	     *
251	     * @param ownerFieldsDto the owner fields from the request body
252	     * @return {@code 201 Created} with the created owner and its {@code Location} header,
253	     *         or the appropriate rejection status: {@code 400 Bad Request} when the fields
254	     *         are invalid, {@code 429 Too Many Requests} when the day's create cap is
255	     *         reached, or {@code 409 Conflict} when the city is at capacity or the owner's
256	     *         identity key duplicates an existing owner
257	     */
258	    private ResponseEntity<OwnerDto> createNewOwner(OwnerFieldsDto ownerFieldsDto) {
259	        HttpHeaders headers = new HttpHeaders();
260	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
261	        if (!normalizeNewOwner(owner)) {
262	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
263	        }
264	        if (dailyLimitReached(owner.getRegistrationDate())) {
265	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
266	        }
267	        if (cityIsAtCapacity(owner.getCity())) {
268	            return new ResponseEntity<>(HttpStatus.CONFLICT);
269	        }
270	        owner.setHouseholdId(owner.computeHouseholdId());
271	        if (isDuplicateIdentity(owner)) {
272	            return new ResponseEntity<>(HttpStatus.CONFLICT);
273	        }
274	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
275	        List<Owner> householdMembers = findHouseholdMembers(owner);
276	        boolean joinsExistingHousehold = !householdMembers.isEmpty();
277	        boolean declaredHouseholdMember = joinsExistingHousehold && sharesHousehold;
278	        assignDerivedAttributes(owner, declaredHouseholdMember, householdMembers);
279	        this.clinicService.saveOwner(owner);
280	        ownerCreationAuditor.auditOwnerCreated(owner);
281	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
282	        headers.setLocation(UriComponentsBuilder.newInstance()
283	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
284	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
285	    }
