332	     * Normalise the owner's address fields in place to their canonical stored form
333	     * (trimmed, whitespace-collapsed, upper-cased and with common abbreviations
334	     * expanded; see {@link Owner#normalizeAddress(String)}), gathering the whole address
335	     * concern of {@link #normalizeNewOwner} in one place. The structured form is
336	     * preferred: when a non-blank {@code addressLine1} is supplied it (and any
337	     * {@code addressLine2}) is normalised, and the flat {@code address} is composed from
338	     * them — the normalised {@code addressLine1}, with a single space and the normalised
339	     * {@code addressLine2} appended when an {@code addressLine2} is present. Otherwise the
340	     * flat {@code address} is normalised on its own, preserving backward compatibility.
341	     * Either way the canonicalised values are written back so every later household
342	     * comparison and read sees them.
343	     *
344	     * @param owner the freshly-mapped owner whose address fields are being normalised
345	     * @return {@code true} once an address is valid and stored, or {@code false} when
346	     *         neither a structured {@code addressLine1} nor a flat {@code address} is
347	     *         present after normalisation, in which case the request must be rejected
348	     *         with {@code 400 Bad Request}
349	     */
350	    private boolean normalizeAddressFields(Owner owner) {
351	        String addressLine1 = Owner.normalizeAddress(owner.getAddressLine1());
352	        if (!addressLine1.isEmpty()) {
353	            owner.setAddressLine1(addressLine1);
354	            String composed = addressLine1;
355	            String addressLine2 = Owner.normalizeAddress(owner.getAddressLine2());
356	            if (!addressLine2.isEmpty()) {
357	                owner.setAddressLine2(addressLine2);
358	                composed = addressLine1 + " " + addressLine2;
359	            }

650	     * already existed at creation time.
