540	     * Compute the customer code to assign to the candidate owner, de-duplicated against
541	     * every existing owner's customer code. The base code is the owner's computed
542	     * {@code <REGION>-<HASH8>} (see {@link Owner#computeCustomerCode()}); when it does not
543	     * already belong to an existing owner it is used unchanged. Otherwise it collides, and
544	     * {@code -<n>} is appended with the smallest integer {@code n} of 2 or more that yields
545	     * a code no existing owner holds, so the returned customer code is unique. Evaluated
546	     * before the owner is saved, so only pre-existing owners are considered.
547	     *
548	     * @param owner the candidate owner being created, after normalisation
549	     * @return the unique (de-duplicated) customer code to assign
550	     */
551	    private String deduplicatedCustomerCode(Owner owner) {
552	        Set<String> existingCodes = this.clinicService.findAllOwners().stream()
553	            .map(Owner::getCustomerCode)
554	            .filter(code -> code != null)
555	            .collect(java.util.stream.Collectors.toSet());
556	        String base = owner.computeCustomerCode();
557	        if (!existingCodes.contains(base)) {
558	            return base;
559	        }
560	        int n = 2;
561	        while (existingCodes.contains(base + "-" + n)) {
562	            n++;
563	        }
564	        return base + "-" + n;
565	    }
